import React, { useState } from 'react';
import '../styles/theme.css';

export default function Login({ onLoginSuccess }) {
  const [authMode, setAuthMode] = useState('login'); // 'login', 'signup', 'forgot', 'otp'
  const [formData, setFormData] = useState({
    mobile: '',
    password: '',
    name: '',
    confirmPassword: '',
    otp: ''
  });
  const [message, setMessage] = useState('');

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleLoginSubmit = (e) => {
    e.preventDefault();
    if (!formData.mobile || !formData.password) {
      setMessage('Please enter mobile number and password.');
      return;
    }
    onLoginSuccess();
  };

  const handleSignupSubmit = (e) => {
    e.preventDefault();
    if (formData.password !== formData.confirmPassword) {
      setMessage('Passwords do not match!');
      return;
    }
    alert('Account created successfully! Please login.');
    setAuthMode('login');
    setMessage('');
  };

  const handleSendOtp = (e) => {
    e.preventDefault();
    if (!formData.mobile) {
      setMessage('Please enter your registered mobile number.');
      return;
    }
    alert('OTP sent successfully to ' + formData.mobile + ' (Use 1234)');
    setAuthMode('otp');
    setMessage('');
  };

  const handleVerifyOtp = (e) => {
    e.preventDefault();
    if (formData.otp === '1234') {
      alert('OTP verified successfully!');
      setAuthMode('login');
      setMessage('');
    } else {
      setMessage('Invalid OTP. Use 1234');
    }
  };

  return (
    <div style={pageStyle}>
      
      {/* LEFT PANE - CLEAN BRANDING */}
      <div style={leftPaneStyle}>
        <div>
          <div style={{ fontSize: '48px', marginBottom: '15px' }}>🌾</div>
          <h1 style={{ color: '#FFFFFF', fontSize: '40px', fontWeight: '800', margin: '0 0 10px 0', letterSpacing: '-0.5px' }}>
            RK SONS
          </h1>
          <p style={{ color: '#34D399', fontSize: '16px', fontWeight: '600', margin: 0, letterSpacing: '1px' }}>
            GRAIN TRADING & ENTERPRISE OS
          </p>
        </div>
      </div>

      {/* RIGHT PANE - COMPACT MODERN FORM */}
      <div style={rightPaneStyle}>
        <div style={cardWrapperStyle}>
          
          <div style={{ marginBottom: '24px' }}>
            <h2 style={{ color: '#0F172A', margin: '0 0 6px 0', fontSize: '24px', fontWeight: '700' }}>
              {authMode === 'login' && 'Welcome Back'}
              {authMode === 'signup' && 'Create Account'}
              {authMode === 'forgot' && 'Reset Password'}
              {authMode === 'otp' && 'Enter OTP'}
            </h2>
            <p style={{ color: '#64748B', margin: 0, fontSize: '13px' }}>
              {authMode === 'login' && 'Sign in to access your trading dashboard.'}
              {authMode === 'signup' && 'Register a new management account.'}
              {authMode === 'forgot' && 'Enter your mobile to recover password.'}
              {authMode === 'otp' && 'Check your phone for the 4-digit code.'}
            </p>
          </div>

          {message && <div style={errorStyle}>{message}</div>}

          {/* 1. LOGIN */}
          {authMode === 'login' && (
            <form onSubmit={handleLoginSubmit} style={formStyle}>
              <div>
                <label style={labelStyle}>Mobile Number</label>
                <input type="text" name="mobile" value={formData.mobile} onChange={handleChange} placeholder="Enter mobile number" style={inputStyle} required />
              </div>
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '6px' }}>
                  <label style={{ ...labelStyle, marginBottom: 0 }}>Password</label>
                  <span style={linkStyle} onClick={() => { setAuthMode('forgot'); setMessage(''); }}>Forgot?</span>
                </div>
                <input type="password" name="password" value={formData.password} onChange={handleChange} placeholder="••••••••" style={inputStyle} required />
              </div>

              <button type="submit" style={primaryBtn}>Sign In</button>

              <div style={{ textAlign: 'center', fontSize: '13px', color: '#64748B', marginTop: '6px' }}>
                New here? <span style={{ ...linkStyle, fontWeight: '600' }} onClick={() => { setAuthMode('signup'); setMessage(''); }}>Create Account</span>
              </div>
            </form>
          )}

          {/* 2. SIGN UP */}
          {authMode === 'signup' && (
            <form onSubmit={handleSignupSubmit} style={formStyle}>
              <div>
                <label style={labelStyle}>Full Name</label>
                <input type="text" name="name" value={formData.name} onChange={handleChange} placeholder="Enter your name" style={inputStyle} required />
              </div>
              <div>
                <label style={labelStyle}>Mobile Number</label>
                <input type="text" name="mobile" value={formData.mobile} onChange={handleChange} placeholder="Enter mobile number" style={inputStyle} required />
              </div>
              <div>
                <label style={labelStyle}>Password</label>
                <input type="password" name="password" value={formData.password} onChange={handleChange} placeholder="Create password" style={inputStyle} required />
              </div>
              <div>
                <label style={labelStyle}>Confirm Password</label>
                <input type="password" name="confirmPassword" value={formData.confirmPassword} onChange={handleChange} placeholder="Confirm password" style={inputStyle} required />
              </div>

              <button type="submit" style={primaryBtn}>Register</button>

              <div style={{ textAlign: 'center', fontSize: '13px', color: '#64748B', marginTop: '6px' }}>
                Already have an account? <span style={{ ...linkStyle, fontWeight: '600' }} onClick={() => { setAuthMode('login'); setMessage(''); }}>Sign In</span>
              </div>
            </form>
          )}

          {/* 3. FORGOT PASSWORD */}
          {authMode === 'forgot' && (
            <form onSubmit={handleSendOtp} style={formStyle}>
              <div>
                <label style={labelStyle}>Registered Mobile Number</label>
                <input type="text" name="mobile" value={formData.mobile} onChange={handleChange} placeholder="Enter mobile number" style={inputStyle} required />
              </div>

              <button type="submit" style={primaryBtn}>Send OTP</button>

              <div style={{ textAlign: 'center', fontSize: '13px', marginTop: '6px' }}>
                <span style={linkStyle} onClick={() => { setAuthMode('login'); setMessage(''); }}>← Back to Sign In</span>
              </div>
            </form>
          )}

          {/* 4. OTP */}
          {authMode === 'otp' && (
            <form onSubmit={handleVerifyOtp} style={formStyle}>
              <div>
                <label style={labelStyle}>Enter 4-Digit OTP</label>
                <input type="text" name="otp" value={formData.otp} onChange={handleChange} placeholder="1234" maxLength="4" style={{ ...inputStyle, textAlign: 'center', letterSpacing: '8px', fontSize: '18px', fontWeight: 'bold' }} required />
              </div>

              <button type="submit" style={primaryBtn}>Verify OTP</button>

              <div style={{ textAlign: 'center', fontSize: '13px', marginTop: '6px' }}>
                <span style={linkStyle} onClick={() => { setAuthMode('login'); setMessage(''); }}>← Back to Sign In</span>
              </div>
            </form>
          )}

        </div>
      </div>
    </div>
  );
}

